// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createLink, pinLink, getLinkPin, deleteLink } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const linkName = uniqueSuffix("skyramp-pin-reject");
    const linkUrl = uniqueSuffix("https://example.com/skyramp-pin-reject");

    const linksPostResponse = await createLink(
        client,
        headers,
        linkName,
        linkUrl
    );

    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe(linkName);
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe(linkUrl);
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(linksPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const linkId = getResponseValue(linksPostResponse, "response.id");
    const callerId = getResponseValue(linksPostResponse, "response.createdById");

    const linksPinPatchResponse = await pinLink(client, headers, linkId);

    expect(linksPinPatchResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPinPatchResponse, "response.id"), 'id').toBe(linkId);
    expect(getResponseValue(linksPinPatchResponse, "response.name"), 'name').toBe(linkName);
    expect(getResponseValue(linksPinPatchResponse, "response.url"), 'url').toBe(linkUrl);
    expect(getResponseValue(linksPinPatchResponse, "response.pinnedBy.0.id"), 'pinnedBy.0.id').toBe(callerId);
    expect(getResponseValue(linksPinPatchResponse, "response.updatedAt"), 'updatedAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const pinPatchResponse = await pinLink(client, headers, "999999999", 404);

    expect(pinPatchResponse.statusCode, 'status code').toBe(404);
    expect(getResponseValue(pinPatchResponse, "response"), 'response').toBe("Link not found.");

    const abcPinPatchResponse = await pinLink(client, headers, "abc", 400);

    expect(abcPinPatchResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(abcPinPatchResponse, "response"), 'response').toBe("Invalid link ID.");

    const linksPinGetResponse = await getLinkPin(client, headers, linkId);

    expect(linksPinGetResponse.statusCode, 'status code').toBe(405);
    expect(getResponseValue(linksPinGetResponse, "response"), 'response').toBe("Method not allowed.");

    const linksLinksDeleteResponse = await deleteLink(client, headers, linkId);

    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'id').toBe(linkId);
    expect(getResponseValue(linksLinksDeleteResponse, "response.name"), 'name').toBe(linkName);
    expect(getResponseValue(linksLinksDeleteResponse, "response.url"), 'url').toBe(linkUrl);
});
